CREATE VIEW stg_external_rating_resolved AS SELECT DISTINCT s.GameID, s.GameEditionID, s.RatingSourceID, s.RatingTypeID, s.RatingValue, s.RawRatingValue, s.ObservationDate FROM stg_external_rating_normalized AS s WHERE (NOT EXISTS(SELECT 1 FROM dq_external_rating_conflicts AS c WHERE ((c.GameID = s.GameID) AND (c.GameEditionID = s.GameEditionID) AND (c.RatingSourceID = s.RatingSourceID) AND (c.RatingTypeID = s.RatingTypeID))));
